try{
    var els = document.querySelectorAll('.reveal');
    if('IntersectionObserver' in window){
      var obs = new IntersectionObserver(function(entries){
        entries.forEach(function(e){
          if(e.isIntersecting){ e.target.classList.add('visible'); obs.unobserve(e.target); }
        });
      },{threshold:0.1});
      els.forEach(function(el){ obs.observe(el); });
    } else {
      els.forEach(function(el){ el.classList.add('visible'); });
    }
  }catch(err){
    document.querySelectorAll('.reveal').forEach(function(el){ el.classList.add('visible'); });
  }

  function animateCount(el){
    var text = el.textContent.trim();
    var m = text.match(/^(₹?)(\d+(?:\.\d+)?)(.*)$/);
    if(!m) return;
    var prefix = m[1], target = parseFloat(m[2]), suffix = m[3];
    var decimals = m[2].indexOf('.') > -1 ? m[2].split('.')[1].length : 0;
    var duration = 1100, start = null;
    function step(ts){
      if(!start) start = ts;
      var p = Math.min((ts - start) / duration, 1);
      el.textContent = prefix + (target * p).toFixed(decimals) + suffix;
      if(p < 1) requestAnimationFrame(step);
      else el.textContent = prefix + target.toFixed(decimals) + suffix;
    }
    requestAnimationFrame(step);
  }
  function animateNums(container){
    if(!container) return;
    container.querySelectorAll('.num').forEach(function(el){
      if(el.dataset.animated) return;
      el.dataset.animated = '1';
      animateCount(el);
    });
  }
  try{
    setTimeout(function(){ animateNums(document.querySelector('.hero-stats')); }, 450);
    document.querySelectorAll('.reveal').forEach(function(el){
      if('IntersectionObserver' in window){
        var o2 = new IntersectionObserver(function(entries){
          entries.forEach(function(e){ if(e.isIntersecting){ animateNums(e.target); o2.unobserve(e.target); } });
        }, {threshold:0.3});
        o2.observe(el);
      } else { animateNums(el); }
    });
  }catch(err){}

  function setupCarousel(scrollerId, prevId, nextId, dotsId, cardSelector){
    try{
      var track = document.getElementById(scrollerId);
      var dotsWrap = document.getElementById(dotsId);
      var prev = document.getElementById(prevId);
      var next = document.getElementById(nextId);
      if(!track || !dotsWrap) return;
      var cards = track.querySelectorAll(cardSelector);
      cards.forEach(function(c, i){
        var dot = document.createElement('button');
        dot.className = 'car-dot' + (i === 0 ? ' active' : '');
        dot.setAttribute('aria-label', 'Go to slide ' + (i + 1));
        dot.addEventListener('click', function(){ c.scrollIntoView({behavior:'smooth', inline:'start', block:'nearest'}); });
        dotsWrap.appendChild(dot);
      });
      var dots = dotsWrap.querySelectorAll('.car-dot');
      if('IntersectionObserver' in window){
        var io = new IntersectionObserver(function(entries){
          entries.forEach(function(e){
            if(e.isIntersecting){
              var idx = Array.prototype.indexOf.call(cards, e.target);
              dots.forEach(function(d){ d.classList.remove('active'); });
              if(dots[idx]) dots[idx].classList.add('active');
            }
          });
        }, {root:track, threshold:0.6});
        cards.forEach(function(c){ io.observe(c); });
      }
      if(prev) prev.addEventListener('click', function(){ track.scrollBy({left:-track.clientWidth * 0.85, behavior:'smooth'}); });
      if(next) next.addEventListener('click', function(){ track.scrollBy({left:track.clientWidth * 0.85, behavior:'smooth'}); });
    }catch(err){}
  }
  document.querySelectorAll('.exp-card').forEach(function(c){
    c.addEventListener('click', function(){
      var t = c.getAttribute('data-tab');
      if(t){ var r = document.getElementById(t); if(r) r.checked = true; }
    });
  });
  setupCarousel('expScroller', 'expPrev', 'expNext', 'expDots', '.exp-card');

