(function(){
  try{
    var VIDS = ["data:video/mp4;base64,", "data:video/mp4;base64,", "data:video/mp4;base64,", "data:video/mp4;base64,", "data:video/mp4;base64,", "data:video/mp4;base64,", "data:video/mp4;base64,", "data:video/mp4;base64,", "data:video/mp4;base64,"];
    var POSTERS = ["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
    var vids = document.querySelectorAll('.vs-wrap video');
    vids.forEach(function(v){ v.poster = POSTERS[+v.dataset.i]; v.muted = true; v.setAttribute('playsinline',''); });
    if(!('IntersectionObserver' in window)) return;
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        var v = e.target;
        if(e.isIntersecting){
          if(!v.getAttribute('src')){ v.src = VIDS[+v.dataset.i]; }
          var p = v.play(); if(p && p.catch){ p.catch(function(){}); }
        } else { v.pause(); }
      });
    }, {threshold:0.15});
    vids.forEach(function(v){ io.observe(v); });
  }catch(err){}
})();

