(function(){
  try{
    var viewer = document.querySelector('.av-viewer'); if(!viewer) return;
    var META = [["Pabbly Connect", "UTM automation for webinar"], ["Pabbly Connect", "Webinar Registration"], ["n8n", "Website Leads"], ["n8n", "Lead Generation (Paid Funnel)"]];
    var items = [].slice.call(viewer.querySelectorAll('.av-item'));
    var imgs = [].slice.call(viewer.querySelectorAll('.av-stage img'));
    var title = document.getElementById('avTitle'), tool = document.getElementById('avTool');
    function show(i){
      items.forEach(function(el,k){ el.classList.toggle('active', k===i); });
      imgs.forEach(function(im,k){ im.classList.toggle('on', k===i); });
      title.textContent = META[i][1]; tool.textContent = META[i][0];
      var p = items[i].querySelector('.prog'); p.style.animation = 'none'; void p.offsetWidth; p.style.animation = '';
    }
    items.forEach(function(el,i){
      el.addEventListener('click', function(){ show(i); });
      el.querySelector('.prog').addEventListener('animationend', function(){ if(el.classList.contains('active')) show((i+1)%items.length); });
    });
    show(0);
    if('IntersectionObserver' in window){
      new IntersectionObserver(function(es){ es.forEach(function(e){ viewer.classList.toggle('run', e.isIntersecting); }); }, {threshold:0.35}).observe(viewer);
    } else { viewer.classList.add('run'); }
    var lb = document.createElement('div'); lb.className = 'lb'; lb.innerHTML = '<img alt="">'; document.body.appendChild(lb);
    var lbImg = lb.querySelector('img');
    viewer.querySelector('.av-stage').addEventListener('click', function(){
      var on = viewer.querySelector('.av-stage img.on'); if(on){ lbImg.src = on.src; lb.classList.add('open'); }
    });
    lb.addEventListener('click', function(){ lb.classList.remove('open'); });
    document.addEventListener('keydown', function(e){ if(e.key === 'Escape') lb.classList.remove('open'); });
  }catch(err){}
})();

