(function(){
  try{
    function wkCount(el){
      var t = el.getAttribute('data-final') || el.textContent.trim(); el.setAttribute('data-final', t);
      var m = t.match(/^([+₹]*)(\d[\d,]*(?:\.\d+)?)(.*)$/); if(!m){ el.textContent = t; return; }
      var pre = m[1], raw = m[2], suf = m[3];
      var target = parseFloat(raw.replace(/,/g,''));
      var dec = raw.indexOf('.') > -1 ? raw.split('.')[1].length : 0;
      var comma = raw.indexOf(',') > -1, start = null;
      function fmt(v){ var x = v.toFixed(dec); if(comma){ x = Number(x).toLocaleString('en-US'); } return pre + x + suf; }
      function step(ts){
        if(!start) start = ts;
        var p = Math.min((ts - start) / 1000, 1), e = 1 - Math.pow(1 - p, 3);
        el.textContent = fmt(target * e);
        if(p < 1) requestAnimationFrame(step); else el.textContent = t;
      }
      requestAnimationFrame(step);
    }
    function runActive(){
      var r = document.querySelector('.tabs input:checked'); if(!r) return;
      var n = r.id.replace('tab','');
      document.querySelectorAll('.tab-panels .p' + n + ' [data-count]').forEach(wkCount);
    }
    document.querySelectorAll('.tabs input').forEach(function(i){ i.addEventListener('change', runActive); });
    var tabs = document.querySelector('.tabs');
    if(tabs && 'IntersectionObserver' in window){
      var o = new IntersectionObserver(function(es){ es.forEach(function(e){ if(e.isIntersecting){ runActive(); o.unobserve(tabs); } }); }, {threshold:0.25});
      o.observe(tabs);
    }
  }catch(err){}
})();

