(function(){try{
  var lb=document.createElement('div'); lb.className='pv-lb'; lb.innerHTML='<img alt="">'; document.body.appendChild(lb);
  lb.addEventListener('click',function(){lb.classList.remove('open');});
  document.addEventListener('keydown',function(e){if(e.key==='Escape')lb.classList.remove('open');});
  var sc=document.getElementById('dgScroll'), cards=[].slice.call(sc.children), now=document.getElementById('dgNow'), cur=0;
  function upd(){
    var best=0,d=1e9; cards.forEach(function(c,k){var x=Math.abs(c.offsetLeft-sc.offsetLeft-sc.scrollLeft-4); if(x<d){d=x;best=k;}});
    cur=best; now.textContent=('0'+(best+1)).slice(-2);
  }
  function go(k){k=Math.max(0,Math.min(cards.length-1,k)); sc.scrollTo({left:cards[k].offsetLeft-sc.offsetLeft-4,behavior:'smooth'});}
  sc.addEventListener('scroll',function(){window.requestAnimationFrame(upd);},{passive:true});
  document.getElementById('dgPrev').addEventListener('click',function(){go(cur-1);});
  document.getElementById('dgNext').addEventListener('click',function(){go(cur+1);});
  cards.forEach(function(c,k){c.querySelector('[data-zoom]').addEventListener('click',function(){
    lb.querySelector('img').src=c.querySelector('img').src; lb.classList.add('open');});});
  upd();
}catch(e){}})();